exercises.solution:
def recherche(liste_triee, x):
    debut, fin = 0, len(liste_triee) - 1
    while debut <= fin:
        milieu = (debut + fin) // 2
        if liste_triee[milieu] == x:
            return milieu
        if liste_triee[milieu] < x:
            debut = milieu + 1
        else:
            fin = milieu - 1
    return -1

print(recherche([3, 8, 15, 23, 42, 57], 23))

