exercises.solution:
def compter_feuilles(donnee):
    if isinstance(donnee, dict):
        return sum(compter_feuilles(v) for v in donnee.values())
    elif isinstance(donnee, list):
        return sum(compter_feuilles(v) for v in donnee)
    return 1

print(compter_feuilles({"a": 1, "b": {"c": 2, "d": [3, 4]}}))

